__SIMBAKES_PANDUAN__.peserta = {"id":"peserta","judul":"Panduan Peserta","judulPanjang":"Panduan Penggunaan SIMBAKES untuk Peserta","deskripsi":"Panduan lengkap penggunaan aplikasi bagi peserta/pengguna.","edisi":"Edisi 2026","palet":{"primary":"#0d7a72","primaryD":"#0a5d57","accent":"#17928a"},"css":".pbb{\n  --primary:#0d7a72; --primary-d:#0a5d57; --primary-l:#7db5ae; --accent:#17928a;\n  --header-fill:#3d6a64; --page-bg:#f4f6f5; --section-bg:#eff2f1; --card-bg:#e7efed;\n  --stripe:#f0f4f3; --border:#cddcd8; --text:#1c2b29; --muted:#5d7370;\n  --success:#3d7a52; --success-bg:#e9f3ec; --warning:#8a6d3b; --warning-bg:#f4efe3;\n  --error:#91443c; --error-bg:#f5e9e7; --info:#4a6d8c; --info-bg:#e9eff5;\n}\n.pbb,.pbb *{ box-sizing:border-box; }\n.pbb p, .pbb td, .pbb li{ line-break:strict; text-align:justify; hyphens:auto; }\n.pbb /* ============ COVER ============ */\n.frontpage{ width:794px; height:1123px; position:relative; background:var(--page-bg);\n  break-after:page; overflow:hidden; border:none; }\n.pbb .cov-l1{ position:absolute; inset:0; overflow:hidden; z-index:1; }\n.pbb .cov-grid{ position:absolute; inset:0;\n  background-image:repeating-linear-gradient(0deg,rgba(13,122,114,.05) 0 .6px,transparent .6px 52px),\n                   repeating-linear-gradient(90deg,rgba(13,122,114,.05) 0 .6px,transparent .6px 52px); }\n.pbb .cov-circles{ position:absolute; right:0; bottom:0; width:430px; height:430px; }\n.pbb .cov-l2{ position:absolute; inset:0; z-index:2; }\n.pbb .cov-anchor{ position:absolute; left:95px; top:112px; bottom:112px; width:6px; background:var(--accent); }\n.pbb .cov-l3{ position:absolute; inset:0; z-index:3; }\n.pbb .cov-kicker{ position:absolute; left:175px; top:150px; font-size:12.5px; font-weight:600;\n  letter-spacing:4px; color:var(--primary-d); opacity:.62; text-transform:uppercase; }\n.pbb .cov-hero{ position:absolute; left:175px; top:236px; font-family:'Plus Jakarta Sans','Inter',sans-serif;\n  font-size:66px; font-weight:800; letter-spacing:1px; color:var(--text); line-height:1.1; }\n.pbb .cov-rule{ position:absolute; left:178px; top:352px; width:66px; height:5px; background:var(--accent); border-radius:3px; }\n.pbb .cov-sub{ position:absolute; left:175px; top:404px; font-family:'Plus Jakarta Sans','Inter',sans-serif;\n  font-size:26px; font-weight:700; color:var(--primary-d); line-height:1.3; max-width:520px; }\n.pbb .cov-sum{ position:absolute; left:175px; top:560px; font-size:15.5px; line-height:1.75;\n  color:var(--muted); max-width:480px; text-align:left; }\n.pbb .cov-chips{ position:absolute; left:175px; top:756px; display:flex; gap:10px; flex-wrap:wrap; max-width:540px; }\n.pbb .cov-chip{ border:1px solid var(--border); background:#fff; border-radius:999px;\n  padding:6px 16px; font-size:12px; font-weight:600; color:var(--primary-d); }\n.pbb .cov-meta{ position:absolute; left:175px; top:852px; font-size:14px; color:var(--text); }\n.pbb .cov-meta b{ font-weight:700; color:var(--primary-d); }\n.pbb .cov-meta .sub{ display:block; margin-top:4px; font-size:12.5px; color:var(--muted); }\n.pbb .cov-foot{ position:absolute; left:175px; right:60px; bottom:72px; display:flex;\n  justify-content:space-between; align-items:baseline; font-size:11.5px; letter-spacing:1.5px;\n  color:var(--muted); text-transform:uppercase; }\n.pbb .cov-foot b{ color:var(--primary-d); font-weight:700; }\n.pbb /* ============ TOC PAGE ============ */\n.toc-page{ width:794px; height:1123px; break-after:page; background:#fff; position:relative;\n  padding:72px 96px 48px 96px; }\n.pbb .toc-kicker{ font-size:11.5px; letter-spacing:3px; font-weight:700; color:var(--accent); text-transform:uppercase; }\n.pbb .toc-title{ font-family:'Plus Jakarta Sans','Inter',sans-serif; font-size:32px; font-weight:800;\n  color:var(--text); margin:6px 0 4px 0; }\n.pbb .toc-sub{ font-size:13px; color:var(--muted); margin-bottom:26px; text-align:left; }\n.pbb .titem{ display:flex; gap:14px; padding:6.5px 0; border-bottom:1px dashed var(--border); }\n.pbb .titem:last-of-type{ border-bottom:none; }\n.pbb .tnum{ width:30px; flex:0 0 30px; font-weight:800; color:var(--accent); font-size:13px; }\n.pbb .tblock{ flex:1; min-width:0; }\n.pbb .trow{ display:flex; align-items:baseline; }\n.pbb .ttl{ font-weight:600; font-size:14px; color:var(--text); }\n.pbb .tline{ flex:1; border-bottom:1px dotted var(--border); margin:0 10px; transform:translateY(-3px); min-width:24px; }\n.pbb .tpage{ font-weight:700; color:var(--primary); font-variant-numeric:tabular-nums; font-size:13px; }\n.pbb .tdesc{ display:block; font-size:11.5px; color:var(--muted); margin-top:1px; text-align:left; }\n.pbb .toc-note{ margin-top:18px; border:1px solid var(--border); background:var(--section-bg);\n  border-radius:12px; padding:12px 16px; font-size:12px; color:var(--text); }\n.pbb .toc-note b{ color:var(--primary-d); }\n.pbb /* ============ MAIN CONTENT ============ */\n.main-content{ padding:58px 64px 46px 64px; background:#fff; }\n.pbb .chapter-header{ break-after:avoid; break-inside:avoid; margin-top:28px; }\n.pbb .chapter-header.first{ margin-top:0; }\n.pbb .ch-tag{ font-size:11px; letter-spacing:2.5px; font-weight:800; color:var(--accent); text-transform:uppercase; }\n.pbb .ch-title{ font-family:'Plus Jakarta Sans','Inter',sans-serif; font-size:25px; font-weight:800;\n  color:var(--text); margin:3px 0 0 0; line-height:1.25; }\n.pbb .ch-div{ display:flex; align-items:center; gap:0; margin:10px 0 14px 0; }\n.pbb .ch-div .bar{ width:52px; height:3.5px; background:var(--accent); border-radius:2px; }\n.pbb .ch-div .hair{ flex:1; height:1px; background:var(--border); }\n.pbb .lead{ font-size:14.5px; color:var(--muted); margin:0 0 10px 0; }\n.pbb h3.sec{ font-family:'Plus Jakarta Sans','Inter',sans-serif; font-size:16px; font-weight:700;\n  color:var(--primary-d); margin:18px 0 8px 0; break-after:avoid; page-break-after:avoid; }\n.pbb p{ margin:0 0 10px 0; }\n.pbb /* callout */\n.callout{ border-radius:10px; padding:11px 15px 11px 16px; margin:12px 0; break-inside:avoid;\n  page-break-inside:avoid; border-left:4px solid; font-size:13px; }\n.pbb .callout .co-label{ font-size:10px; letter-spacing:1.8px; font-weight:800; display:block; margin-bottom:3px; text-transform:uppercase; }\n.pbb .callout p{ margin:0; }\n.pbb .callout.tip{ background:var(--success-bg); border-color:var(--success); color:#275137; }\n.pbb .callout.tip .co-label{ color:var(--success); }\n.pbb .callout.warn{ background:var(--warning-bg); border-color:var(--warning); color:#6d5628; }\n.pbb .callout.warn .co-label{ color:var(--warning); }\n.pbb .callout.danger{ background:var(--error-bg); border-color:var(--error); color:#753630; }\n.pbb .callout.danger .co-label{ color:var(--error); }\n.pbb .callout.info{ background:var(--info-bg); border-color:var(--info); color:#3a5570; }\n.pbb .callout.info .co-label{ color:var(--info); }\n.pbb /* steps */\n.steps{ list-style:none; margin:10px 0; padding:0; counter-reset:step; }\n.pbb .steps li{ position:relative; padding:0 0 6px 42px; margin-bottom:8px; counter-increment:step;\n  break-inside:avoid; page-break-inside:avoid; }\n.pbb .steps li::before{ content:counter(step,decimal-leading-zero); position:absolute; left:0; top:1px;\n  width:29px; height:29px; border-radius:9px; background:var(--primary); color:#fff; font-weight:700;\n  font-size:12px; display:flex; align-items:center; justify-content:center; }\n.pbb .steps b.st{ display:block; font-weight:700; color:var(--text); margin-bottom:1px; }\n.pbb .steps p{ margin:0 0 4px 0; font-size:13.5px; }\n.pbb /* tables */\ntable.data{ width:100%; border-collapse:collapse; margin:12px 0; font-size:12.8px; }\n.pbb table.data thead{ display:table-header-group; }\n.pbb table.data thead th{ background:var(--header-fill); color:#fff; text-align:left; padding:8px 12px;\n  font-weight:600; font-size:11.8px; letter-spacing:.4px; }\n.pbb table.data thead th:first-child{ border-radius:8px 0 0 0; }\n.pbb table.data thead th:last-child{ border-radius:0 8px 0 0; }\n.pbb table.data tbody td{ padding:7.5px 12px; border-bottom:1px solid var(--border); vertical-align:top; }\n.pbb table.data tbody tr{ break-inside:avoid; page-break-inside:avoid; }\n.pbb table.data tbody tr:nth-child(odd){ background:var(--stripe); }\n.pbb table.data ul{ margin:0; padding-left:16px; }\n.pbb table.data p{ margin:0; }\n.pbb /* badges */\n.badge{ display:inline-block; padding:1.5px 10px; border-radius:999px; font-size:11px; font-weight:700; white-space:nowrap; }\n.pbb .b-verify{ background:var(--info-bg); color:var(--info); }\n.pbb .b-ok{ background:var(--success-bg); color:var(--success); }\n.pbb .b-no{ background:var(--error-bg); color:var(--error); }\n.pbb .b-rev{ background:var(--warning-bg); color:var(--warning); }\n.pbb .b-off{ background:#e8eaec; color:#57616d; }\n.pbb /* flow */\n.flow{ display:flex; flex-wrap:wrap; gap:10px; margin:14px 0 10px 0; max-width:100%; }\n.pbb .fstep{ flex:1 1 128px; min-width:118px; max-width:100%; background:var(--card-bg);\n  border:1px solid var(--border); border-radius:11px; padding:10px 12px;\n  break-inside:avoid; page-break-inside:avoid; overflow-wrap:break-word; }\n.pbb .fstep .fn{ font-size:10px; font-weight:800; letter-spacing:1.5px; color:var(--accent); }\n.pbb .fstep .ft{ font-weight:700; font-size:12.6px; margin-top:2px; color:var(--text); }\n.pbb .fstep .fd{ font-size:11px; color:var(--muted); margin-top:2px; line-height:1.5; text-align:left; }\n.pbb /* menu cards */\n.cards3{ display:grid; grid-template-columns:repeat(3,1fr); gap:12px; margin:12px 0; }\n.pbb .cards2{ display:grid; grid-template-columns:repeat(2,1fr); gap:12px; margin:12px 0; }\n.pbb .mcard{ border:1px solid var(--border); border-radius:12px; padding:13px 15px; background:#fff;\n  break-inside:avoid; page-break-inside:avoid; }\n.pbb .mcard .mc-ico{ width:34px; height:34px; border-radius:10px; background:var(--card-bg);\n  color:var(--primary-d); font-weight:800; font-size:15px; display:flex; align-items:center;\n  justify-content:center; margin-bottom:8px; font-family:'Plus Jakarta Sans','Inter',sans-serif; }\n.pbb .mcard .mc-t{ font-weight:700; font-size:13.5px; color:var(--text); margin-bottom:3px; }\n.pbb .mcard .mc-d{ font-size:12px; color:var(--muted); line-height:1.55; text-align:left; }\n.pbb /* faq */\n.faq-item{ break-inside:avoid; page-break-inside:avoid; border:1px solid var(--border);\n  border-left:4px solid var(--primary); border-radius:10px; padding:11px 15px; margin-bottom:10px; background:#fff; }\n.pbb .faq-q{ font-weight:700; font-size:13.6px; color:var(--text); }\n.pbb .faq-a{ margin-top:4px; font-size:13.2px; color:var(--text); }\n.pbb .faq-a p{ margin:0; }\n.pbb /* misc */\n.hl{ background:var(--card-bg); padding:0 5px; border-radius:5px; font-weight:600; color:var(--primary-d); }\n.pbb kbd{ font-family:'Inter',monospace; background:var(--section-bg); border:1px solid var(--border);\n  border-radius:6px; padding:1px 7px; font-size:12px; font-weight:600; color:var(--primary-d); }\n.pbb .small{ font-size:12px; color:var(--muted); }\n.pbb ul.plain{ margin:6px 0 10px 0; padding-left:20px; }\n.pbb ul.plain li{ margin-bottom:4px; break-inside:avoid; }\n.pbb /* ============ ENDING ============ */\n.ending{ width:794px; height:1123px; break-before:page; page-break-before:always;\n  background:var(--page-bg); position:relative; overflow:hidden; }\n.pbb .end-frame{ position:absolute; inset:56px 44px; border:1.5px solid var(--border); border-radius:4px; }\n.pbb .end-inner{ position:absolute; inset:56px 44px; display:flex; flex-direction:column;\n  align-items:center; justify-content:center; text-align:center; padding:0 90px; }\n.pbb .end-logo{ width:58px; height:58px; border-radius:16px; background:var(--primary); color:#fff;\n  font-family:'Plus Jakarta Sans','Inter',sans-serif; font-weight:800; font-size:22px;\n  display:flex; align-items:center; justify-content:center; margin-bottom:22px; }\n.pbb .end-title{ font-family:'Plus Jakarta Sans','Inter',sans-serif; font-size:27px; font-weight:800; color:var(--text); margin-bottom:12px; }\n.pbb .end-text{ font-size:14px; color:var(--muted); line-height:1.8; max-width:470px; text-align:center; }\n.pbb .end-contact{ margin-top:30px; display:flex; gap:12px; }\n.pbb .end-cbox{ border:1px solid var(--border); background:#fff; border-radius:12px; padding:13px 20px; text-align:left; }\n.pbb .end-cbox .l{ font-size:10.5px; letter-spacing:1.5px; font-weight:800; color:var(--accent); text-transform:uppercase; }\n.pbb .end-cbox .n{ font-weight:700; font-size:14px; color:var(--text); margin-top:2px; }\n.pbb .end-cbox .p{ font-size:12.5px; color:var(--muted); }\n.pbb .end-foot{ position:absolute; bottom:88px; left:90px; right:90px; text-align:center;\n  font-size:11px; letter-spacing:1.2px; color:var(--muted); text-transform:uppercase; }","cover":"<div class=\"frontpage\">\n  <div class=\"cov-l1\">\n    <div class=\"cov-grid\"><\/div>\n    <svg class=\"cov-circles\" viewBox=\"0 0 430 430\" fill=\"none\">\n      <circle cx=\"285\" cy=\"285\" r=\"200\" stroke=\"#0d7a72\" stroke-width=\"0.7\" opacity=\"0.14\"/>\n      <circle cx=\"315\" cy=\"305\" r=\"200\" stroke=\"#0d7a72\" stroke-width=\"0.7\" opacity=\"0.22\"/>\n      <circle cx=\"345\" cy=\"325\" r=\"200\" stroke=\"#0d7a72\" stroke-width=\"0.7\" opacity=\"0.32\"/>\n      <circle cx=\"392\" cy=\"60\" r=\"7\" fill=\"#17928a\" opacity=\"0.5\"/>\n      <circle cx=\"365\" cy=\"90\" r=\"3\" fill=\"#17928a\" opacity=\"0.3\"/>\n    <\/svg>\n  <\/div>\n  <div class=\"cov-l2\">\n    <div class=\"cov-anchor\"><\/div>\n  <\/div>\n  <div class=\"cov-l3\">\n    <div class=\"cov-kicker\">Buku Panduan Pengguna &middot; Edisi Peserta<\/div>\n    <div class=\"cov-hero\">SIMBAKES<\/div>\n    <div class=\"cov-rule\"><\/div>\n    <div class=\"cov-sub\">Panduan Penggunaan<br>untuk Peserta<\/div>\n    <div class=\"cov-sum\">Sistem Informasi Manajemen Beasiswa Tematik Bidang Kesehatan\n      Pemerintah Kabupaten Kutai Kartanegara. Buku ini memandu Anda langkah demi langkah:\n      mendaftarkan akun peserta, masuk ke portal, mengajukan rekomendasi beasiswa,\n      memantau status pengajuan, hingga melihat hasil penetapan penerima.<\/div>\n    <div class=\"cov-chips\">\n      <span class=\"cov-chip\">13 Bab Panduan<\/span>\n      <span class=\"cov-chip\">Langkah Ringkas Berurutan<\/span>\n      <span class=\"cov-chip\">FAQ &amp; Kontak PIC<\/span>\n    <\/div>\n    <div class=\"cov-meta\"><b>Edisi 2026<\/b> &middot; Disusun sesuai tampilan Platform SIMBAKES v2.0\n      <span class=\"sub\">Dinas Kesehatan Kab. Kutai Kartanegara<\/span><\/div>\n    <div class=\"cov-foot\"><span><b>SIMBAKES<\/b> &middot; Beasiswa Tematik Bidang Kesehatan<\/span><span>&copy; 2026<\/span><\/div>\n  <\/div>\n<\/div>","toc":[{"n":1,"judul":"Tentang Panduan Ini","desc":"Untuk siapa buku ini ditulis dan bagaimana membacanya"},{"n":2,"judul":"Mengenal SIMBAKES","desc":"Fungsi platform dan alur besar program beasiswa"},{"n":3,"judul":"Persiapan Sebelum Memulai","desc":"Perangkat, dokumen wajib, ketentuan foto, dan surat pernyataan"},{"n":4,"judul":"Mendaftarkan Akun Peserta","desc":"Membuat akun baru dan menunggu verifikasi admin"},{"n":5,"judul":"Login ke Portal Peserta","desc":"Masuk ke sistem menggunakan username dan password"},{"n":6,"judul":"Portal Peserta: Tiga Menu Utama","desc":"Ajukan rekomendasi, cek status, dan cek penetapan"},{"n":7,"judul":"Mengisi Formulir Ajukan Rekomendasi","desc":"Enam bagian formulir beserta ketentuan isian dan dokumen"},{"n":8,"judul":"Mengirim Pengajuan & Nomor Register","desc":"Konfirmasi akhir, layar sukses, dan unduh bukti pendaftaran"},{"n":9,"judul":"Memantau Status Pengajuan","desc":"Makna setiap status dan cara memperbaiki data bila diminta"},{"n":10,"judul":"Melihat Hasil Penetapan","desc":"Menampilkan status kelulusan, SK, dan data akademik"},{"n":11,"judul":"Menu Referensi","desc":"Roadmap Kebutuhan, Lulus Tes Masuk PT, Petunjuk Penggunaan"},{"n":12,"judul":"Pertanyaan yang Sering Diajukan","desc":"Jawaban atas kendala yang paling sering dialami peserta"},{"n":13,"judul":"Bantuan & Kontak","desc":"Menghubungi PIC program bila menemui kendala"}],"bab":[{"n":1,"judul":"Tentang Panduan Ini","html":"<div class=\"chapter-header first\">\n    <div class=\"ch-tag\">Bab 01<\/div>\n    <div class=\"ch-title\">Tentang Panduan Ini<\/div>\n    <div class=\"ch-div\"><span class=\"bar\"><\/span><span class=\"hair\"><\/span><\/div>\n  <\/div>\n  <p class=\"lead\">Buku panduan khusus untuk peserta Beasiswa Tematik Bidang Kesehatan Kabupaten Kutai Kartanegara.<\/p>\n  <p>Buku ini disusun agar Anda dapat menggunakan platform <b>SIMBAKES<\/b> secara mandiri,\n  dari proses paling awal hingga hasil akhir. Seluruh langkah di dalamnya mengikuti tampilan\n  dan urutan menu persis seperti yang ada di platform, sehingga apa yang Anda baca di buku ini\n  akan Anda temukan juga di layar. Pembahasan diatur berurutan mengikuti perjalanan Anda sebagai\n  peserta: menyiapkan dokumen, membuat akun, masuk ke portal, mengisi formulir pengajuan,\n  memantau proses, dan akhirnya melihat hasil penetapan.<\/p>\n  <p>Buku ini diperuntukkan bagi <b>calon dan peserta aktif beasiswa tematik bidang kesehatan<\/b>,\n  yaitu tenaga kesehatan maupun calon tenaga kesehatan yang ingin melanjutkan pendidikan sesuai\n  roadmap kebutuhan Dinas Kesehatan Kabupaten Kutai Kartanegara. Apabila Anda bertugas sebagai\n  admin atau operator di Dinas Kesehatan, gunakan buku pasangan panduan ini yang berjudul\n  <i>Panduan Penggunaan untuk Admin &amp; Operator<\/i>, karena alur kerja dan menu yang tersedia\n  untuk admin berbeda dengan yang tersedia untuk peserta.<\/p>\n  <h3 class=\"sec\">Cara Membaca Buku Ini<\/h3>\n  <p>Setiap bab terdiri atas penjelasan singkat, langkah bernomor, dan tabel ringkas yang bisa\n  Anda baca cepat. Langkah bernomor sebaiknya diikuti berurutan karena satu langkah sering\n  menjadi syarat bagi langkah berikutnya. Tiga jenis kotak penanda digunakan di seluruh buku:<\/p>\n  <div class=\"callout tip\"><span class=\"co-label\">Tips<\/span>\n    <p>Saran praktis yang membuat pekerjaan Anda lebih mudah, misalnya cara menyusun dokumen agar cepat diverifikasi.<\/p><\/div>\n  <div class=\"callout warn\"><span class=\"co-label\">Penting<\/span>\n    <p>Hal yang wajib diperhatikan. Mengabaikan kotak ini dapat menyebabkan pengajuan tertunda atau ditolak.<\/p><\/div>\n  <div class=\"callout info\"><span class=\"co-label\">Catatan<\/span>\n    <p>Informasi tambahan yang membantu Anda memahami maksud suatu langkah, namun tidak wajib diikuti.<\/p><\/div>\n  <p>Istilah yang ditulis dengan sorotan hijau, seperti <span class=\"hl\">Layanan<\/span> atau\n  <span class=\"hl\">Kirim Pengajuan<\/span>, adalah nama menu dan tombol yang tampil persis di\n  platform. Bila teks di layar Anda sedikit berbeda karena pembaruan platform, gunakan nama yang\n  paling mendekati. Nomor telepon, alamat, dan ketentuan yang disebut dalam buku ini merupakan\n  data resmi program pada saat buku diterbitkan.<\/p>"},{"n":2,"judul":"Mengenal SIMBAKES","html":"<div class=\"chapter-header\">\n    <div class=\"ch-tag\">Bab 02<\/div>\n    <div class=\"ch-title\">Mengenal SIMBAKES<\/div>\n    <div class=\"ch-div\"><span class=\"bar\"><\/span><span class=\"hair\"><\/span><\/div>\n  <\/div>\n  <p class=\"lead\">Memahami apa itu SIMBAKES dan bagaimana alur program beasiswa berjalan di dalamnya.<\/p>\n  <p><b>SIMBAKES<\/b> adalah <b>S<\/b>istem <b>I<\/b>nformasi <b>M<\/b>anajemen <b>B<\/b>easiswa\n  <b>T<\/b>ematik Bidang <b>K<\/b>esehatan, sebuah platform daring milik Pemerintah Kabupaten\n  Kutai Kartanegara yang dikelola oleh Dinas Kesehatan. SIMBAKES menjadi satu-satunya jalur\n  resmi untuk mengajukan rekomendasi beasiswa tematik bidang kesehatan, mulai dari pendaftaran\n  akun peserta, pengajuan rekomendasi, proses verifikasi berkas oleh petugas, hingga\n  pengumuman penetapan penerima beasiswa beserta surat keputusannya (SK).<\/p>\n  <p>Program ini bertujuan mendukung pengembangan sumber daya manusia (SDM) kesehatan di\n  Kabupaten Kutai Kartanegara. Jurusan dan kuota yang tersedia disusun berdasarkan\n  <i>Roadmap Kebutuhan<\/i> Dinas Kesehatan, sehingga bidang studi yang Anda tuju sebaiknya\n  selaras dengan kebutuhan unit kerja di wilayah Kutai Kartanegara, baik di puskesmas maupun\n  rumah sakit daerah.<\/p>\n  <h3 class=\"sec\">Alur Besar Program<\/h3>\n  <p>Perjalanan Anda sebagai peserta melalui lima tahap utama berikut. Setiap tahap dijelaskan\n  rinci pada bab-bab selanjutnya:<\/p>\n  <div class=\"flow\">\n    <div class=\"fstep\"><div class=\"fn\">TAHAP 1<\/div><div class=\"ft\">Daftar Akun<\/div><div class=\"fd\">Membuat akun peserta dan menunggu persetujuan admin.<\/div><\/div>\n    <div class=\"fstep\"><div class=\"fn\">TAHAP 2<\/div><div class=\"ft\">Login Portal<\/div><div class=\"fd\">Masuk ke portal peserta menggunakan akun yang sudah disetujui.<\/div><\/div>\n    <div class=\"fstep\"><div class=\"fn\">TAHAP 3<\/div><div class=\"ft\">Ajukan Rekomendasi<\/div><div class=\"fd\">Mengisi formulir lengkap beserta foto dan dokumen PDF.<\/div><\/div>\n    <div class=\"fstep\"><div class=\"fn\">TAHAP 4<\/div><div class=\"ft\">Verifikasi Admin<\/div><div class=\"fd\">Petugas memeriksa berkas; Anda memantau status pengajuan.<\/div><\/div>\n    <div class=\"fstep\"><div class=\"fn\">TAHAP 5<\/div><div class=\"ft\">Penetapan<\/div><div class=\"fd\">Melihat hasil kelulusan dan SK penerima beasiswa.<\/div><\/div>\n  <\/div>\n  <p>Perhatikan bahwa tahap 1 sampai 3 sepenuhnya dikerjakan oleh Anda sebagai peserta, sedangkan\n  tahap 4 dan 5 dikerjakan oleh tim Dinas Kesehatan. Peran Anda pada tahap akhir adalah memantau\n  status secara berkala melalui menu <span class=\"hl\">Cek Status Pengajuan<\/span> dan\n  <span class=\"hl\">Cek Status Penetapan<\/span> agar tidak ada pemberitahuan yang terlewat,\n  misalnya permintaan perbaikan data yang hanya diberi waktu terbatas.<\/p>\n  <div class=\"callout info\"><span class=\"co-label\">Catatan<\/span>\n    <p>Seluruh data yang Anda masukkan tersimpan aman di server resmi Dinas Kesehatan dan hanya\n    dapat dilihat oleh Anda serta petugas berwenang yang memverifikasi berkas.<\/p><\/div>"},{"n":3,"judul":"Persiapan Sebelum Memulai","html":"<div class=\"chapter-header\">\n    <div class=\"ch-tag\">Bab 03<\/div>\n    <div class=\"ch-title\">Persiapan Sebelum Memulai<\/div>\n    <div class=\"ch-div\"><span class=\"bar\"><\/span><span class=\"hair\"><\/span><\/div>\n  <\/div>\n  <p class=\"lead\">Pastikan perangkat dan seluruh dokumen siap agar proses pengajuan berjalan sekali jalan.<\/p>\n  <p>Pengajuan yang bermutu diawali dengan persiapan yang rapi. Sebelum membuka platform,\n  sediakan waktu untuk memeriksa dua hal: perangkat yang akan digunakan dan kelengkapan\n  dokumen. Pengalaman menunjukkan sebagian besar keterlambatan verifikasi bukan karena\n  kesalahan sistem, melainkan karena dokumen tidak lengkap, tidak terbaca, atau tidak sesuai\n  ketentuan. Dengan menyiapkan semuanya sejak awal, Anda dapat menyelesaikan formulir dalam\n  satu kali duduk dan tidak perlu mengulang unggahan.<\/p>\n  <h3 class=\"sec\">Perangkat dan Koneksi<\/h3>\n  <ul class=\"plain\">\n    <li>Gunakan komputer, laptop, atau ponsel dengan browser modern terbaru (Chrome, Edge, Firefox, atau Safari).<\/li>\n    <li>Pastikan koneksi internet stabil, terutama saat mengunggah file foto dan dokumen PDF yang berukuran besar.<\/li>\n    <li>Siapkan versi digital dokumen dalam satu folder agar mudah dipilih saat mengunggah.<\/li>\n  <\/ul>\n  <h3 class=\"sec\">Dokumen Wajib<\/h3>\n  <p>Seluruh dokumen di bawah ini harus dipindai atau difoto dengan jelas, lalu digabungkan\n  menjadi <b>satu file PDF<\/b> dengan urutan sebagai berikut:<\/p>\n  <table class=\"data\">\n    <thead><tr><th style=\"width:38px\">No<\/th><th style=\"width:220px\">Dokumen<\/th><th>Ketentuan<\/th><\/tr><\/thead>\n    <tbody>\n      <tr><td>1<\/td><td>KTP<\/td><td>Pindaian jelas, sesuai NIK yang Anda isikan pada formulir.<\/td><\/tr>\n      <tr><td>2<\/td><td>Kartu Keluarga (KK)<\/td><td>Halaman yang memuat data Anda.<\/td><\/tr>\n      <tr><td>3<\/td><td>Ijazah Terakhir<\/td><td>Bila belum wisuda, boleh menggunakan Surat Keterangan Lulus (SKL).<\/td><\/tr>\n      <tr><td>4<\/td><td>Transkrip Nilai<\/td><td>Transkrip pendidikan terakhir yang sah.<\/td><\/tr>\n      <tr><td>5<\/td><td>STR (Surat Teregistrasi)<\/td><td>Hanya untuk yang sudah memiliki; tidak wajib bagi yang belum.<\/td><\/tr>\n      <tr><td>6<\/td><td>Surat Permohonan &amp; Surat Kesediaan Pendayagunaan<\/td><td>Sesuai format instansi; ditandatangani pihak yang berwenang.<\/td><\/tr>\n    <\/tbody>\n  <\/table>\n  <div class=\"callout warn\"><span class=\"co-label\">Penting<\/span>\n    <p>File dokumen kelengkapan berupa <b>satu PDF gabungan<\/b> berisi keenam dokumen di atas\n    dengan urutan yang sama seperti tabel, dengan ukuran <b>maksimal 10 MB<\/b>. Urutan yang rapi\n    mempercepat pekerjaan verifikator.<\/p><\/div>\n  <h3 class=\"sec\">Foto Pasfoto<\/h3>\n  <p>Foto pasfoto diunggah terpisah dari dokumen PDF. Ketentuannya: <b>format JPG atau PNG<\/b>,\n  ukuran cetak <b>4&times;6 cm<\/b>, <b>latar belakang MERAH<\/b>, ukuran file <b>maksimal 5 MB<\/b>.\n  Gunakan foto terbaru yang wajah, kepala, dan pundak terlihat jelas tanpa penutup yang\n  mengaburkan identitas. Foto inilah yang akan tampil di kartu data Anda selama proses\n  verifikasi dan pada hasil penetapan, jadi pastikan hasilnya pantas dan profesional.<\/p>\n  <h3 class=\"sec\">Surat Pernyataan<\/h3>\n  <p>Formulir pengajuan menyediakan tombol <span class=\"hl\">Download Template<\/span> untuk surat\n  pernyataan resmi. Unduh templat tersebut, isi data yang diminta, cetak, tangandatangani, lalu\n  pindai dan simpan sebagai PDF untuk diunggah kembali pada bagian yang telah disediakan.\n  Surat pernyataan yang belum ditandatangani dianggap tidak lengkap.<\/p>"},{"n":4,"judul":"Mendaftarkan Akun Peserta","html":"<div class=\"chapter-header\">\n    <div class=\"ch-tag\">Bab 04<\/div>\n    <div class=\"ch-title\">Mendaftarkan Akun Peserta<\/div>\n    <div class=\"ch-div\"><span class=\"bar\"><\/span><span class=\"hair\"><\/span><\/div>\n  <\/div>\n  <p class=\"lead\">Akun peserta dibuat sekali saja dan menjadi identitas Anda di seluruh layanan SIMBAKES.<\/p>\n  <p>Semua layanan pengajuan di SIMBAKES hanya dapat diakses oleh peserta yang sudah login.\n  Karena itu, hal pertama yang harus Anda lakukan adalah mendaftarkan akun. Pendaftaran gratis\n  dan hanya membutuhkan beberapa menit. Setelah formulir pendaftaran terkirim, akun Anda berstatus\n  <span class=\"badge b-rev\">Menunggu Persetujuan<\/span> dan akan diperiksa oleh admin Dinas\n  Kesehatan, umumnya dalam <b>1&ndash;2 hari kerja<\/b>. Anda belum dapat login sebelum akun disetujui.<\/p>\n  <h3 class=\"sec\">Langkah Mendaftar<\/h3>\n  <ol class=\"steps\">\n    <li><b class=\"st\">Buka halaman utama SIMBAKES.<\/b>\n      <p>Tunggu beberapa detik hingga halaman pembuka selesai memuat dan dashboard utama tampil.<\/p><\/li>\n    <li><b class=\"st\">Klik menu Layanan, lalu pilih Ajukan Rekomendasi.<\/b>\n      <p>Karena Anda belum login, sistem otomatis membuka jendela <i>Login Peserta<\/i>.<\/p><\/li>\n    <li><b class=\"st\">Klik tautan &ldquo;Daftar di Sini&rdquo;.<\/b>\n      <p>Tautan ini berada di bagian bawah jendela login dan akan membuka halaman\n      <b>Formulir Pendaftaran Akun Peserta<\/b> pada tab baru.<\/p><\/li>\n    <li><b class=\"st\">Isi seluruh isian formulir.<\/b>\n      <p>Gunakan tabel berikut sebagai panduan mengisi setiap kolom.<\/p><\/li>\n    <li><b class=\"st\">Klik tombol <span class=\"hl\">DAFTARKAN AKUN<\/span>.<\/b>\n      <p>Tunggu hingga muncul panel <b>&ldquo;Pendaftaran Berhasil!&rdquo;<\/b> yang berisi ringkasan\n      akun Anda. Simpan username dan password dengan baik.<\/p><\/li>\n  <\/ol>\n  <h3 class=\"sec\">Panduan Isian Formulir Pendaftaran<\/h3>\n  <table class=\"data\">\n    <thead><tr><th style=\"width:170px\">Isian<\/th><th>Ketentuan Pengisian<\/th><\/tr><\/thead>\n    <tbody>\n      <tr><td>Nama Lengkap<\/td><td>Sesuai identitas/KTP, maksimal 150 karakter.<\/td><\/tr>\n      <tr><td>NIK<\/td><td>Tepat <b>16 digit<\/b> angka sesuai KTP. Penghitung digit tersedia di bawah kolom.<\/td><\/tr>\n      <tr><td>Email<\/td><td>Email aktif; digunakan sebagai alternatif login selain username.<\/td><\/tr>\n      <tr><td>Username<\/td><td>Huruf kecil dan/atau angka, <b>minimal 4 karakter<\/b>. Sistem otomatis mengubah huruf menjadi kecil semua.<\/td><\/tr>\n      <tr><td>Jurusan Tujuan<\/td><td>Pilih dari daftar yang telah disesuaikan dengan roadmap kebutuhan Dinas Kesehatan.<\/td><\/tr>\n      <tr><td>Password<\/td><td><b>Minimal 8 karakter<\/b>; ketik ulang pada kolom konfirmasi hingga keduanya sama.<\/td><\/tr>\n    <\/tbody>\n  <\/table>\n  <div class=\"callout tip\"><span class=\"co-label\">Tips<\/span>\n    <p>Buat password yang mudah Anda ingat namun sulit ditebak orang lain, misalnya gabungan\n    kata, angka, dan tanda baca. Jangan menggunakan tanggal lahir atau nomor telepon.\n    Simpan catatan akun di tempat yang aman.<\/p><\/div>\n  <div class=\"callout warn\"><span class=\"co-label\">Penting<\/span>\n    <p>Setelah mendaftar, akun Anda <b>diverifikasi admin Dinas Kesehatan terlebih dahulu<\/b>\n    sebelum dapat digunakan login. Periksa login Anda secara berkala; bila lebih dari\n    2 hari kerja belum disetujui, hubungi PIC pada Bab 13.<\/p><\/div>"},{"n":5,"judul":"Login ke Portal Peserta","html":"<div class=\"chapter-header\">\n    <div class=\"ch-tag\">Bab 05<\/div>\n    <div class=\"ch-title\">Login ke Portal Peserta<\/div>\n    <div class=\"ch-div\"><span class=\"bar\"><\/span><span class=\"hair\"><\/span><\/div>\n  <\/div>\n  <p class=\"lead\">Masuk ke sistem setelah akun Anda disetujui admin.<\/p>\n  <p>Login dilakukan melalui jendela <i>Login Peserta<\/i>, bukan melalui panel admin yang berada\n  di bagian bawah menu samping. Pastikan Anda memasukkan kredensial pada jendela yang benar\n  agar sesi tercatat sebagai peserta. Bila akun Anda masih menunggu persetujuan, login akan\n  ditolak dengan pemberitahuan; tunggu hingga admin menyetujui akun Anda.<\/p>\n  <ol class=\"steps\">\n    <li><b class=\"st\">Buka halaman utama SIMBAKES.<\/b><\/li>\n    <li><b class=\"st\">Klik menu <span class=\"hl\">Layanan<\/span> di menu samping.<\/b>\n      <p>Jendela <i>Login Peserta<\/i> akan terbuka otomatis karena ketiga layanan bersifat khusus peserta terdaftar.<\/p><\/li>\n    <li><b class=\"st\">Masukkan username dan password Anda.<\/b>\n      <p>Username atau email yang terdaftar dapat digunakan. Periksa ejaan dan penggunaan huruf kapital.<\/p><\/li>\n    <li><b class=\"st\">Klik tombol <span class=\"hl\">MASUK<\/span>.<\/b>\n      <p>Apabila berhasil, portal peserta dengan tiga kartu layanan akan tampil. Nama Anda\n      tercatat di pojok kanan atas portal.<\/p><\/li>\n  <\/ol>\n  <div class=\"callout danger\"><span class=\"co-label\">Lupa Password?<\/span>\n    <p>SIMBAKES tidak memiliki reset mandiri demi keamanan data. Hubungi PIC program\n    (Bab 13) melalui WhatsApp dengan menyertakan nama lengkap dan NIK untuk bantuan\n    pemulihan akun. Jangan mendaftarkan akun ganda dengan NIK yang sama.<\/p><\/div>\n  <div class=\"callout info\"><span class=\"co-label\">Catatan<\/span>\n    <p>Sesi login akan berakhir otomatis bila Anda keluar dari sistem atau perangkat ditinggalkan\n    dalam waktu lama. Cukup login kembali untuk melanjutkan; data pengajuan yang sudah terkirim\n    tetap tersimpan aman.<\/p><\/div>"},{"n":6,"judul":"Portal Peserta: Tiga Menu Utama","html":"<div class=\"chapter-header\">\n    <div class=\"ch-tag\">Bab 06<\/div>\n    <div class=\"ch-title\">Portal Peserta: Tiga Menu Utama<\/div>\n    <div class=\"ch-div\"><span class=\"bar\"><\/span><span class=\"hair\"><\/span><\/div>\n  <\/div>\n  <p class=\"lead\">Seluruh layanan peserta terkonsentrasi pada tiga kartu yang mudah dikenali.<\/p>\n  <p>Setelah login, Anda dibawa ke portal peserta yang menampilkan tiga kartu layanan. Ketiga\n  kartu ini juga dapat diakses melalui menu <span class=\"hl\">Layanan<\/span> pada menu samping\n  kiri: <span class=\"hl\">Ajukan Rekomendasi<\/span>, <span class=\"hl\">Cek Status Pengajuan<\/span>,\n  dan <span class=\"hl\">Cek Status Penetapan<\/span>. Gunakan tabel di bawah untuk menentukan\n  menu mana yang tepat untuk kebutuhan Anda saat ini.<\/p>\n  <div class=\"cards3\">\n    <div class=\"mcard\"><div class=\"mc-ico\">1<\/div>\n      <div class=\"mc-t\">Ajukan Rekomendasi<\/div>\n      <div class=\"mc-d\">Formulir pengajuan beasiswa: data pribadi, pekerjaan, rencana studi, kontak, foto, dan dokumen PDF.<\/div><\/div>\n    <div class=\"mcard\"><div class=\"mc-ico\">2<\/div>\n      <div class=\"mc-t\">Cek Status Pengajuan<\/div>\n      <div class=\"mc-d\">Melacak kemajuan pengajuan menggunakan NIK atau Nomor Register, lengkap dengan tombol bukti dan dokumen.<\/div><\/div>\n    <div class=\"mcard\"><div class=\"mc-ico\">3<\/div>\n      <div class=\"mc-t\">Cek Status Penetapan<\/div>\n      <div class=\"mc-d\">Melihat hasil akhir: status kelulusan, SK, dan data akademik Anda sebagai penerima.<\/div><\/div>\n  <\/div>\n  <h3 class=\"sec\">Kapan Menggunakan Menu yang Mana<\/h3>\n  <table class=\"data\">\n    <thead><tr><th>Kondisi Anda<\/th><th style=\"width:210px\">Menu yang Digunakan<\/th><\/tr><\/thead>\n    <tbody>\n      <tr><td>Belum pernah mengajukan dan ingin mendaftar beasiswa<\/td><td><span class=\"hl\">Ajukan Rekomendasi<\/span><\/td><\/tr>\n      <tr><td>Sudah mengajukan dan ingin mengetahui perkembangannya<\/td><td><span class=\"hl\">Cek Status Pengajuan<\/span><\/td><\/tr>\n      <tr><td>Diminta memperbaiki data oleh verifikator<\/td><td><span class=\"hl\">Cek Status Pengajuan<\/span> &rarr; tombol perbaikan<\/td><\/tr>\n      <tr><td>Ingin melihat keputusan akhir dan SK<\/td><td><span class=\"hl\">Cek Status Penetapan<\/span><\/td><\/tr>\n    <\/tbody>\n  <\/table>\n  <p>Selain ketiga layanan tersebut, menu <span class=\"hl\">Beranda<\/span> pada sisi kiri\n  menyediakan informasi umum yang terbuka tanpa login: <span class=\"hl\">Roadmap Kebutuhan<\/span>,\n  <span class=\"hl\">Lulus Tes Masuk PT<\/span>, dan <span class=\"hl\">Petunjuk Penggunaan<\/span>.\n  Pembahasan lengkapnya ada di Bab 11.<\/p>"},{"n":7,"judul":"Mengisi Formulir Ajukan Rekomendasi","html":"<div class=\"chapter-header\">\n    <div class=\"ch-tag\">Bab 07<\/div>\n    <div class=\"ch-title\">Mengisi Formulir Ajukan Rekomendasi<\/div>\n    <div class=\"ch-div\"><span class=\"bar\"><\/span><span class=\"hair\"><\/span><\/div>\n  <\/div>\n  <p class=\"lead\">Inti dari seluruh proses: enam bagian formulir yang menentukan kelengkapan berkas Anda.<\/p>\n  <p>Formulir <span class=\"hl\">Ajukan Rekomendasi<\/span> terdiri atas enam bagian. Beberapa isian\n  terisi otomatis, sisanya wajib diisi lengkap dan benar. Sebelum mulai, pastikan dokumen dari\n  Bab 3 sudah siap di perangkat Anda. Isian bertanda <b>*<\/b> bersifat wajib; formulir tidak\n  dapat dikirim bila ada yang kosong. Data yang Anda isikan akan muncul pada kartu verifikasi\n  petugas, sehingga kecocokan dengan dokumen pendukung sangat penting.<\/p>\n\n  <h3 class=\"sec\">Bagian 1 &mdash; Informasi Registrasi<\/h3>\n  <p><b>Nomor Register<\/b> dan <b>Tanggal &amp; Waktu Pengajuan<\/b> terisi otomatis oleh sistem,\n  jangan diubah. Selanjutnya unggah <b>Foto Pasfoto<\/b>: klik kotak unggah, pilih file foto dari\n  perangkat, dan pratinjau akan tampil. Ketentuan foto: JPG/PNG, pasfoto 4&times;6 cm, latar\n  MERAH, maksimal 5 MB. Bila file yang terpilih keliru, klik tanda &times; pada kotak pratinjau\n  untuk menghapusnya lalu pilih ulang.<\/p>\n\n  <h3 class=\"sec\">Bagian 2 &mdash; Data Pribadi<\/h3>\n  <table class=\"data\">\n    <thead><tr><th style=\"width:190px\">Isian<\/th><th>Ketentuan<\/th><\/tr><\/thead>\n    <tbody>\n      <tr><td>NIK<\/td><td>Tepat 16 digit angka sesuai KTP; kolom hanya menerima angka.<\/td><\/tr>\n      <tr><td>Nama Lengkap<\/td><td>Sesuai KTP, tanpa singkatan.<\/td><\/tr>\n      <tr><td>Tempat &amp; Tanggal Lahir<\/td><td>Pilih tanggal melalui kalender pada kolom tanggal lahir.<\/td><\/tr>\n      <tr><td>Alamat KTP<\/td><td>Alamat sesuai KTP lengkap dengan RT/RW.<\/td><\/tr>\n      <tr><td>Alamat Domisili<\/td><td>Alamat tempat tinggal saat ini.<\/td><\/tr>\n      <tr><td>Lama Domisili<\/td><td>Pilih salah satu: kurang dari 1 tahun; 1&ndash;3 tahun; 3&ndash;5 tahun; lebih dari 5 tahun.<\/td><\/tr>\n    <\/tbody>\n  <\/table>\n\n  <h3 class=\"sec\">Bagian 3 &mdash; Data Pekerjaan<\/h3>\n  <p>Pilih <b>Pekerjaan<\/b> dari daftar: PNS, PPPK, Honorer, Karyawan BLUD, BKKD, Mahasiswa,\n  atau Belum Bekerja. Pilih <b>Posisi<\/b> sesuai kondisi Anda saat ini: <i>Sedang Tes Masuk PT<\/i>,\n  <i>On Going<\/i> (sedang menjalani studi), atau <i>Lulus Tes Masuk PT<\/i>. Isi <b>Unit Kerja /\n  Institusi Asal<\/b> dengan nama lengkap instansi Anda, misalnya nama puskesmas, rumah sakit,\n  atau universitas. Pada <b>Penjelasan/Narasi Singkat<\/b>, tuliskan alasan mengajukan rekomendasi,\n  tujuan studi, serta dampak yang diharapkan bagi pengembangan SDM kesehatan di Kutai\n  Kartanegara. Narasi yang jelas membantu verifikator memahami kesiapan Anda.<\/p>\n\n  <h3 class=\"sec\">Bagian 4 &mdash; Rencana Studi<\/h3>\n  <p><b>Jurusan Tujuan<\/b> dikelompokkan menjadi tiga: <i>Kedokteran &amp; Spesialisasi<\/i>\n  (dokter, dokter gigi, hingga puluhan spesialisasi), <i>Keperawatan &amp; Kebidanan<\/i>\n  (Ners, Profesi Bidan, magister manajemen keperawatan/kebidanan), dan <i>Tenaga Kesehatan\n  Lainnya<\/i> (Apoteker, Nutrisionis, Radiografer, dan lainnya). Pilih jurusan yang tersedia\n  pada <span class=\"hl\">Roadmap Kebutuhan<\/span> agar peluangnya terbuka. Lalu lengkapi:<\/p>\n  <ul class=\"plain\">\n    <li><b>Jenjang Pendidikan<\/b>: D3, D4, D4 + Profesi, S-1 + Profesi, Dokter Spesialis (Sp-1/Sp-2), Magister (S2), Doktor (S3), atau Dokter Subspesialis.<\/li>\n    <li><b>Unit Tujuan Pemanfaatan<\/b>: Dinas Kesehatan (Puskesmas), salah satu dari empat Puskesmas terpilih, atau salah satu dari empat RSUD daerah.<\/li>\n    <li><b>Rencana Tahun Studi<\/b>: tahun mulai studi yang direncanakan (2026&ndash;2030).<\/li>\n  <\/ul>\n\n  <h3 class=\"sec\">Bagian 5 &mdash; Informasi Kontak<\/h3>\n  <p>Isi <b>Nomor Handphone<\/b>, <b>Nomor WhatsApp<\/b>, dan <b>Email Aktif<\/b>. Nomor WhatsApp\n  sangat penting karena menjadi jalur komunikasi tercepat bila verifikator perlu menghubungi\n  Anda. Gunakan nomor yang Anda sendiri pegang dan selalu aktif, bukan nomor orang lain.<\/p>\n\n  <h3 class=\"sec\">Bagian 6 &mdash; Dokumen Pendukung<\/h3>\n  <p>Unggah tiga hal pada bagian ini:<\/p>\n  <ol class=\"steps\">\n    <li><b class=\"st\">Dokumen Kelengkapan (satu PDF gabungan).<\/b>\n      <p>Berisi KTP, KK, Ijazah/SKL, Transkrip Nilai, STR (bila ada), serta Surat Permohonan\n      dan Surat Kesediaan Pendayagunaan, dengan urutan pada Bab 3. Ukuran maksimal 10 MB.<\/p><\/li>\n    <li><b class=\"st\">Template Surat Pernyataan.<\/b>\n      <p>Klik <span class=\"hl\">Download Template<\/span>, isi data, cetak, tangandatangani,\n      pindai menjadi PDF.<\/p><\/li>\n    <li><b class=\"st\">Unggah surat pernyataan yang sudah ditandatangani.<\/b>\n      <p>Pilih file PDF hasil pindaian pada kolom unggah. Surat tanpa tanda tangan tidak sah.<\/p><\/li>\n  <\/ol>\n  <div class=\"callout warn\"><span class=\"co-label\">Penting<\/span>\n    <p>Periksa ulang seluruh isian sebelum melanjutkan ke Bab 8. Kesalahan data pribadi yang\n    dikirim baru dapat diperbaiki melalui mekanisme <i>Perbaikan Data<\/i> setelah verifikator\n    meminta revisi (Bab 9), yang berarti waktu verifikasi Anda tertunda.<\/p><\/div>"},{"n":8,"judul":"Mengirim Pengajuan & Nomor Register","html":"<div class=\"chapter-header\">\n    <div class=\"ch-tag\">Bab 08<\/div>\n    <div class=\"ch-title\">Mengirim Pengajuan &amp; Nomor Register<\/div>\n    <div class=\"ch-div\"><span class=\"bar\"><\/span><span class=\"hair\"><\/span><\/div>\n  <\/div>\n  <p class=\"lead\">Tahap akhir pengajuan: konfirmasi, layar sukses, dan simpan bukti pendaftaran.<\/p>\n  <p>Setelah seluruh bagian formulir terisi, gulir ke bagian bawah halaman dan klik tombol\n  <span class=\"hl\">Kirim Pengajuan<\/span>. Proses pengiriman memindahkan seluruh data dan file\n  Anda ke server SIMBAKES; tunggu hingga selesai dan jangan menutup halaman selama proses\n  berlangsung, terutama bila koneksi Anda sedang lambat.<\/p>\n  <ol class=\"steps\">\n    <li><b class=\"st\">Klik <span class=\"hl\">Kirim Pengajuan<\/span>.<\/b>\n      <p>Bila ada isian wajib yang belum lengkap, sistem menandai bagian yang perlu diperbaiki; lengkapi lalu kirim ulang.<\/p><\/li>\n    <li><b class=\"st\">Perhatikan layar sukses &ldquo;Pengajuan Berhasil Dikirim&rdquo;.<\/b>\n      <p>Layar ini menampilkan <b>Nomor Register<\/b> berformat <kbd>REG-SIMBAKES-XXXXXXXXXX<\/kbd>,\n      tanggal pengajuan, dan status awal <span class=\"badge b-rev\">Diajukan<\/span>.<\/p><\/li>\n    <li><b class=\"st\">Klik <span class=\"hl\">Unduh Bukti Pendaftaran<\/span>.<\/b>\n      <p>Simpan bukti pendaftaran sebagai arsip pribadi; dokumen ini mencantumkan nomor register Anda.<\/p><\/li>\n    <li><b class=\"st\">Klik <span class=\"hl\">Cek Status Pengajuan<\/span> untuk mencoba fitur pelacakan.<\/b>\n      <p>Langkah ini memastikan data Anda sudah dapat dicari di sistem.<\/p><\/li>\n  <\/ol>\n  <div class=\"callout warn\"><span class=\"co-label\">Penting<\/span>\n    <p><b>Simpan Nomor Register Anda.<\/b> Nomor ini adalah kunci untuk melacak pengajuan\n    tanpa harus mengingat NIK, dan menjadi rujukan ketika berkomunikasi dengan PIC.\n    Nomor register juga tercantum pada bukti pendaftaran yang Anda unduh.<\/p><\/div>"},{"n":9,"judul":"Memantau Status Pengajuan","html":"<div class=\"chapter-header\">\n    <div class=\"ch-tag\">Bab 09<\/div>\n    <div class=\"ch-title\">Memantau Status Pengajuan<\/div>\n    <div class=\"ch-div\"><span class=\"bar\"><\/span><span class=\"hair\"><\/span><\/div>\n  <\/div>\n  <p class=\"lead\">Setiap pengajuan bergerak melalui lima status; ketahui artinya agar tidak salah langkah.<\/p>\n  <p>Buka <span class=\"hl\">Cek Status Pengajuan<\/span>, masukkan <b>NIK<\/b> (16 digit) atau\n  <b>Nomor Register<\/b> pada kolom pencarian, lalu klik tombol <span class=\"hl\">Cek Status<\/span>.\n  Hasil pencarian menampilkan kartu berisi data lengkap pengajuan Anda beserta status terkini.\n  Cek secara berkala, terutama pada periode verifikasi, karena permintaan perbaikan data\n  disampaikan melalui status ini.<\/p>\n  <table class=\"data\">\n    <thead><tr><th style=\"width:180px\">Status<\/th><th>Arti dan Langkah Anda<\/th><\/tr><\/thead>\n    <tbody>\n      <tr><td><span class=\"badge b-verify\">Proses Verifikasi<\/span><\/td>\n        <td>Berkas sedang diperiksa petugas. Tidak ada tindakan diperlukan; pantau secara berkala.<\/td><\/tr>\n      <tr><td><span class=\"badge b-ok\">Disetujui<\/span><\/td>\n        <td>Pengajuan dinyatakan lolos seleksi berkas. Tunggu proses penetapan pada tahap berikutnya.<\/td><\/tr>\n      <tr><td><span class=\"badge b-no\">Ditolak<\/span><\/td>\n        <td>Pengajuan tidak memenuhi persyaratan. Baca alasan yang tertera dan hubungi PIC bila perlu klarifikasi.<\/td><\/tr>\n      <tr><td><span class=\"badge b-rev\">Perbaikan<\/span><\/td>\n        <td>Verifikator meminta revisi data atau dokumen. Segera buka form perbaikan (lihat di bawah).<\/td><\/tr>\n      <tr><td><span class=\"badge b-off\">Batal<\/span><\/td>\n        <td>Pengajuan tidak diproses lagi (misalnya ditarik atau digantikan pengajuan resmi lainnya).<\/td><\/tr>\n    <\/tbody>\n  <\/table>\n  <h3 class=\"sec\">Memperbaiki Data Bila Diminta<\/h3>\n  <p>Ketika status Anda menjadi <span class=\"badge b-rev\">Perbaikan<\/span>, tombol form perbaikan\n  muncul pada kartu hasil cek status. Formulir perbaikan berisi data pengajuan Anda yang sudah\n  terisi; ubah hanya bagian yang diminta verifikator, termasuk mengganti foto bila diperlukan.\n  Setelah Anda menyimpan perbaikan, status otomatis kembali ke\n  <span class=\"badge b-verify\">Proses Verifikasi<\/span> dan antrian pemeriksaan dimulai dari awal.\n  Karena itu selesaikan perbaikan sesegera mungkin agar tidak tertinggal dari gelombang verifikasi.<\/p>\n  <div class=\"callout tip\"><span class=\"co-label\">Tips<\/span>\n    <p>Isi salah satu saja antara NIK atau Nomor Register pada kolom pencarian, tidak perlu\n    keduanya. Bila NIK Anda gagal ditemukan, pastikan tidak ada salah ketik; NIK yang benar\n    selalu menemukan data pengajuan Anda.<\/p><\/div>"},{"n":10,"judul":"Melihat Hasil Penetapan","html":"<div class=\"chapter-header\">\n    <div class=\"ch-tag\">Bab 10<\/div>\n    <div class=\"ch-title\">Melihat Hasil Penetapan<\/div>\n    <div class=\"ch-div\"><span class=\"bar\"><\/span><span class=\"hair\"><\/span><\/div>\n  <\/div>\n  <p class=\"lead\">Hasil akhir program: status kelulusan, surat keputusan, dan data akademik Anda.<\/p>\n  <p>Penetapan penerima beasiswa diterbitkan oleh Dinas Kesehatan setelah tahap verifikasi\n  selesai. Anda tidak perlu menghubungi siapa pun untuk mengetahui hasilnya; cukup buka\n  <span class=\"hl\">Cek Status Penetapan<\/span> dan masukkan <b>NIK<\/b> 16 digit yang terdaftar\n  pada pengajuan beasiswa Anda, lalu klik tombol <span class=\"hl\">Cek Penetapan<\/span>.<\/p>\n  <ol class=\"steps\">\n    <li><b class=\"st\">Buka <span class=\"hl\">Layanan &rarr; Cek Status Penetapan<\/span>.<\/b><\/li>\n    <li><b class=\"st\">Masukkan NIK 16 digit.<\/b>\n      <p>Kolom hanya menerima angka. NIK harus sama dengan yang Anda gunakan pada pengajuan.<\/p><\/li>\n    <li><b class=\"st\">Klik <span class=\"hl\">Cek Penetapan<\/span> dan baca kartu hasil.<\/b>\n      <p>Kartu hasil menampilkan foto penerima, nomor register, nama lengkap, NIK, status\n      kelulusan, serta data akademik: jurusan, jenjang, perguruan tinggi, dan unit kerja\n      tujuan penempatan.<\/p><\/li>\n  <\/ol>\n  <p>Perhatikan status kelulusan pada kartu hasil. Status <span class=\"badge b-ok\">Lulus<\/span>\n  berarti Anda ditetapkan sebagai penerima beasiswa; informasi SK dan kewajiban lanjutan akan\n  diberitahukan oleh Dinas Kesehatan melalui jalur yang tercantum pada pengumuman resmi.\n  Status <span class=\"badge b-rev\">Pending<\/span> atau <span class=\"badge b-verify\">Dalam Proses<\/span>\n  berarti penetapan belum selesai &mdash; pantau kembali di lain waktu. Status\n  <span class=\"badge b-no\">Ditolak<\/span> berarti Anda belum ditetapkan pada periode ini;\n  Anda tetap dapat mengikuti periode berikutnya sesuai ketentuan program.<\/p>\n  <div class=\"callout warn\"><span class=\"co-label\">Penting<\/span>\n    <p>Bila NIK Anda benar namun kartu penetapan tidak ditemukan, pengajuan Anda kemungkinan\n    masih dalam tahap verifikasi (Bab 9). Penetapan baru muncul setelah pengajuan dinyatakan\n    <span class=\"badge b-ok\">Disetujui<\/span> dan diproses menjadi SK.<\/p><\/div>"},{"n":11,"judul":"Menu Referensi","html":"<div class=\"chapter-header\">\n    <div class=\"ch-tag\">Bab 11<\/div>\n    <div class=\"ch-title\">Menu Referensi<\/div>\n    <div class=\"ch-div\"><span class=\"bar\"><\/span><span class=\"hair\"><\/span><\/div>\n  <\/div>\n  <p class=\"lead\">Tiga menu beranda yang membantu Anda merencanakan pengajuan dengan tepat.<\/p>\n  <h3 class=\"sec\">Roadmap Kebutuhan<\/h3>\n  <p>Menu <span class=\"hl\">Roadmap Kebutuhan<\/span> menampilkan kebutuhan tenaga kesehatan\n  Dinas Kesehatan per bidang: jurusan, kualifikasi awal yang diminta, jenis pendidikan,\n  perguruan tinggi tujuan, pekerjaan yang diprioritaskan, tahun studi, jumlah kuota, kuota\n  yang sudah terisi, sisa kuota, serta unit pendayaguna. Gunakan data ini untuk memilih\n  <b>Jurusan Tujuan<\/b> pada formulir (Bab 7). Memilih jurusan dengan sisa kuota besar\n  meningkatkan peluang Anda, dan memilih sesuai kebutuhan unit kerja memperkuat narasi\n  pengajuan Anda.<\/p>\n  <h3 class=\"sec\">Lulus Tes Masuk PT<\/h3>\n  <p>Menu <span class=\"hl\">Lulus Tes Masuk PT<\/span> menampilkan daftar peserta yang telah\n  dinyatakan lulus tes masuk perguruan tinggi, dikelompokkan berdasarkan jurusan tujuan.\n  Menu ini berguna sebagai gambaran kompetisi dan capaian peserta pada tiap bidang studi.\n  Bila nama Anda muncul di sini, pastikan pula status penetapan Anda di\n  <span class=\"hl\">Cek Status Penetapan<\/span>.<\/p>\n  <h3 class=\"sec\">Petunjuk Penggunaan<\/h3>\n  <p>Menu <span class=\"hl\">Petunjuk Penggunaan<\/span> di dalam platform berisi ringkasan singkat\n  cara menggunakan SIMBAKES: mengakses platform, mengajukan rekomendasi, mendaftar akun, dan\n  cek status. Buku yang sedang Anda baca ini merupakan versi lengkap dan lebih rinci dari\n  petunjuk ringkas tersebut, termasuk FAQ dan kontak PIC.<\/p>"},{"n":12,"judul":"Pertanyaan yang Sering Diajukan","html":"<div class=\"chapter-header\">\n    <div class=\"ch-tag\">Bab 12<\/div>\n    <div class=\"ch-title\">Pertanyaan yang Sering Diajukan<\/div>\n    <div class=\"ch-div\"><span class=\"bar\"><\/span><span class=\"hair\"><\/span><\/div>\n  <\/div>\n  <p class=\"lead\">Jawaban singkat atas kendala yang paling sering dialami peserta.<\/p>\n  <div class=\"faq-item\"><div class=\"faq-q\">Akun saya sudah mendaftar lebih dari 2 hari kerja tapi belum bisa login. Kenapa?<\/div>\n    <div class=\"faq-a\"><p>Setiap akun baru harus disetujui admin Dinas Kesehatan sebelum dapat digunakan. Waktu persetujuan umumnya 1&ndash;2 hari kerja. Bila lebih lama, hubungi PIC dengan menyertakan nama lengkap, NIK, dan username Anda.<\/p><\/div><\/div>\n  <div class=\"faq-item\"><div class=\"faq-q\">Saya lupa password. Bagaimana cara reset?<\/div>\n    <div class=\"faq-a\"><p>Reset mandiri tidak tersedia demi keamanan. Hubungi PIC program melalui WhatsApp (Bab 13) dengan menyertakan identitas. Jangan mendaftarkan akun baru dengan NIK yang sama.<\/p><\/div><\/div>\n  <div class=\"faq-item\"><div class=\"faq-q\">Saya sudah mengirim pengajuan lalu sadar ada data yang salah. Apa yang harus dilakukan?<\/div>\n    <div class=\"faq-a\"><p>Jangan kirim pengajuan baru. Menunggu hingga verifikator memeriksa; bila verifikator meminta revisi, status berubah menjadi Perbaikan dan tombol form perbaikan muncul di Cek Status Pengajuan. Anda juga dapat menghubungi PIC untuk meminta bantuan.<\/p><\/div><\/div>\n  <div class=\"faq-item\"><div class=\"faq-q\">File dokumen saya ditolak atau gagal diunggah. Kenapa?<\/div>\n    <div class=\"faq-a\"><p>Periksa tiga hal: format harus PDF untuk dokumen dan JPG/PNG untuk foto; ukuran maksimal 10 MB untuk dokumen dan 5 MB untuk foto; serta kestabilan koneksi saat mengunggah. Bila file terlalu besar, kompres PDF menggunakan aplikasi pengompres sebelum diunggah ulang.<\/p><\/div><\/div>\n  <div class=\"faq-item\"><div class=\"faq-q\">Foto saya tidak tampil pada kartu status. Apakah pengajuan saya gagal?<\/div>\n    <div class=\"faq-a\"><p>Tidak. Tampilan foto dapat dipengaruhi koneksi atau format file asal, namun data pengajuan tetap tersimpan aman di server. Bila foto tetap tidak muncul pada waktu berbeda dan perangkat berbeda, laporkan kepada PIC beserta nomor register Anda.<\/p><\/div><\/div>\n  <div class=\"faq-item\"><div class=\"faq-q\">Apakah saya bisa mengajukan lebih dari satu jurusan?<\/div>\n    <div class=\"faq-a\"><p>Satu akun mengajukan satu rekomendasi sesuai jurusan tujuan yang dipilih saat pendaftaran akun. Gunakan Roadmap Kebutuhan untuk memilih jurusan yang paling sesuai dengan kualifikasi dan kebutuhan unit kerja Anda.<\/p><\/div><\/div>\n  <div class=\"faq-item\"><div class=\"faq-q\">Kapan hasil penetapan diumumkan?<\/div>\n    <div class=\"faq-a\"><p>Penetapan terbit setelah seluruh gelombang verifikasi selesai. Pantau menu Cek Status Penetapan secara berkala; kartu hasil akan muncul otomatis begitu data penetapan Anda diterbitkan, tanpa perlu registrasi ulang.<\/p><\/div><\/div>\n  <div class=\"faq-item\"><div class=\"faq-q\">Apakah akun saya bisa dipakai di beberapa perangkat?<\/div>\n    <div class=\"faq-a\"><p>Bisa. Akun dapat dipakai dari perangkat apa pun melalui browser, namun hanya satu orang pemilik akun yang berhak menggunakannya. Jangan bagikan password kepada siapa pun, termasuk pihak yang mengaku petugas.<\/p><\/div><\/div>"},{"n":13,"judul":"Bantuan & Kontak","html":"<div class=\"chapter-header\">\n    <div class=\"ch-tag\">Bab 13<\/div>\n    <div class=\"ch-title\">Bantuan &amp; Kontak<\/div>\n    <div class=\"ch-div\"><span class=\"bar\"><\/span><span class=\"hair\"><\/span><\/div>\n  <\/div>\n  <p class=\"lead\">Bila menemui kendala yang tidak terjawab di buku ini, hubungi petugas program.<\/p>\n  <p>Petugas penanggung jawab (PIC) program siap membantu kendala teknis dan administratif:\n  akun belum disetujui, lupa password, data pengajuan keliru, hingga pertanyaan seputar\n  dokumen dan penetapan. Sertakan <b>nama lengkap<\/b>, <b>NIK<\/b>, dan <b>nomor register<\/b>\n  agar kendala Anda dapat ditelusuri dengan cepat.<\/p>\n  <div class=\"cards2\">\n    <div class=\"mcard\"><div class=\"mc-ico\">A<\/div>\n      <div class=\"mc-t\">Mukmin Nasri<\/div>\n      <div class=\"mc-d\">PIC Program SIMBAKES<br>Telepon / WhatsApp:<br><b>0821-3027-5800<\/b><\/div><\/div>\n    <div class=\"mcard\"><div class=\"mc-ico\">B<\/div>\n      <div class=\"mc-t\">Syarifah Putri<\/div>\n      <div class=\"mc-d\">PIC Program SIMBAKES<br>Telepon / WhatsApp:<br><b>0821-5758-0022<\/b><\/div><\/div>\n  <\/div>\n  <div class=\"callout info\"><span class=\"co-label\">Catatan<\/span>\n    <p>Jam layanan mengikuti jam kerja Dinas Kesehatan Kab. Kutai Kartanegara. Pesan di luar\n    jam kerja tetap dapat dikirim dan akan dibalas pada hari kerja berikutnya. Selalu\n    berkomunikasi melalui kontak resmi di atas; SIMBAKES tidak pernah meminta password Anda\n    melalui telepon maupun pesan.<\/p><\/div>"}]};
